THOUGHT: After reviewing the code, I suspect there might be an issue with how empty values are handled in maps. Let me create a test to verify this behavior:

```bash
cat <<'EOF' > test_empty_map_values.go
package main

import (
	"fmt"
	"log"
	"os"

	"github.com/caarlos0/env/v11"
)

type Config struct {
	MapStringString map[string]string `env:"MAP_STRING_STRING"`
}

func main() {
	os.Setenv("MAP_STRING_STRING", "key1:value1,key2:,key3:value3")

	var cfg Config
	if err := env.Parse(&cfg); err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Map: %+v\n", cfg.MapStringString)
}
EOF
```

